def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        # If current interval overlaps or touches the last merged interval
        if current_start <= last_end:
            # Merge them by extending the end time
            merged[-1] = [last_start, max(last_end, current_end)]
        else:
            # No overlap, add current interval to merged list
            merged.append([current_start, current_end])

    return merged

def toposort(nodes, edges):
    # Build adjacency list and in-degree count
    graph = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    # Process edges to build graph and count in-degrees
    for source, dest in edges:
        if source == dest:
            raise ValueError("Cycle detected")
        graph[source].append(dest)
        in_degree[dest] += 1

    # Find all nodes with zero in-degree
    zero_in_degree = sorted([node for node in nodes if in_degree[node] == 0])

    result = []

    while zero_in_degree:
        # Choose lexicographically smallest node
        current = zero_in_degree.pop(0)
        result.append(current)

        # Remove current node and update in-degrees
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                zero_in_degree.append(neighbor)

        # Keep zero_in_degree sorted
        zero_in_degree.sort()

    # Check for cycles
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("Limit must be positive")

    batches = []
    current_batch = []
    current_weight = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("All weights must be positive and not exceed the limit")

        if current_weight + weight > limit:
            if current_batch:
                batches.append(current_batch)
            current_batch = [name]
            current_weight = weight
        else:
            current_batch.append(name)
            current_weight += weight

    if current_batch:
        batches.append(current_batch)

    return batches

def parse_sse(chunks):
    data_lines = []
    buffer = b""
    events = []

    for chunk in chunks:
        buffer += chunk

        # Process complete lines
        while True:
            newline_pos = buffer.find(b'\n')
            if newline_pos == -1:
                break

            line = buffer[:newline_pos]
            buffer = buffer[newline_pos + 1:]

            # Handle CRLF
            if line.endswith(b'\r'):
                line = line[:-1]

            # Parse line
            if not line:
                # Empty line - dispatch event
                if data_lines:
                    events.append('\n'.join(data_lines))
                    data_lines = []
                    if events[-1] == "[DONE]":
                        return events[:-1]
            elif line.startswith(b"data:"):
                # Extract data (remove "data:" and optional space)
                data = line[5:].lstrip()
                data_lines.append(data.decode('utf-8', errors='ignore'))
            # Ignore other lines

    # Handle final event if it's complete
    if data_lines:
        events.append('\n'.join(data_lines))

    # Remove [DONE] and any following events
    try:
        done_index = events.index("[DONE]")
        return events[:done_index]
    except ValueError:
        return events

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("Arguments must be nonnegative")

    if attempt >= 10**9:
        # Handle large attempt values to avoid overflow
        # 2^(10^9) is astronomically large, so we just return cap if it's finite
        if cap == 0:
            return 0.0
        else:
            return float(cap)

    # For small attempts, compute directly
    if base == 0:
        return 0.0

    # Calculate base * 2^attempt
    result = base * (1 << attempt)  # Using bit shift for efficiency

    # Return minimum of result and cap
    if cap == 0:
        return 0.0
    else:
        return min(result, cap)

def fifo_admit(active, queued, budget, slots):
    # Check if any queued reservation exceeds the whole budget
    for reservation in queued:
        if reservation > budget:
            raise ValueError("Queued reservation exceeds budget")

    admitted = active[:]
    remaining = queued[:]
    used_tokens = sum(admitted)
    used_slots = len(admitted)

    # Process queued requests in FIFO order
    i = 0
    while i < len(remaining):
        request = remaining[i]
        if used_tokens + request <= budget and used_slots < slots:
            admitted.append(request)
            used_tokens += request
            used_slots += 1
            remaining.pop(i)
        else:
            # Skip this request (but don't increment i)
            i += 1

    return (admitted, remaining)
